'use strict';
let draft=null,verifyStep=0,verifyService='bank',verifyDraft={};
const fiat=c=>['USD','EUR','GBP'].includes(c), opened=c=>db.accounts.some(a=>a.currency===c);
function gate(service){if(db.verification[service].status==='approved')return true;modal('先完成身份认证',`<p>${service==='card'?'卡片服务':'银行服务'}需要独立认证。完成后即可继续。</p>`,btn('取消','close')+btn('前往认证','goto','verify','primary'));return false}
function bindForm(id,handler){$(id).onsubmit=e=>{e.preventDefault();handler(new FormData(e.target))}}
const formError='<div class="error" id="form-error" role="alert"></div>';
function footerForm(text){return formError+`<div class="dialog-foot">${btn('取消','close')}<button class="button primary">${text}</button></div></form>`}
function verify(service){verifyService=service;verifyStep=0;verifyDraft={...db.verification[service].data};if(['approved','pending'].includes(db.verification[service].status)){modal('已提交认证资料',summary(Object.entries(verifyDraft).filter(([k])=>k!=='agree').map(([k,v])=>[esc(k),esc(v)]))+note('证明文件只保留文件名。'),btn('关闭','close'));return}verifyRender()}
function verifyFields(){if(person.type==='enterprise')return [
[['企业名称',db.name],['企业注册号','DEMO-2026'],['企业网站','https://example.com'],['成立日期','2020-01-01','date'],['公司类型','有限责任公司'],['注册管辖区','中国香港'],['注册地址','香港示例路 18 号'],['营业地址','香港示例路 18 号'],['行业','软件服务'],['员工数量','10–50'],['业务范围','技术服务'],['企业介绍','为企业提供软件服务']],
[['法定代表人姓名','陈悦'],['角色','董事'],['出生日期','1990-01-01','date'],['国籍','中国'],['证件类型','护照'],['证件号码','DEMO-PASSPORT'],['居住地址','示例路 18 号'],['股东姓名','陈悦'],['持股比例','100%'],['产品 / 服务说明','软件服务'],['资金来源','营业收入']],
[['企业注册证明','','file'],['企业地址证明','','file'],['法定代表人证件','','file'],['股东证明','','file']]
];return [
[['姓','陈'],['名','悦'],['中间名',''],['出生日期','1990-01-01','date'],['国籍','中国'],['出生国家','中国'],['出生城市','上海'],['证件类型','护照'],['证件号码','DEMO-PASSPORT']],
[['居住国家','中国香港'],['城市','香港'],['地址行 1','示例路 18 号'],['地址行 2',''],['邮政编码','000000'],['手机号','+85260000000'],['就业状态','在职'],['职业','产品经理'],['资金来源','工资'],['账户用途','个人日常收付款'],['预计每月收付金额','1000 USD'],['是否替他人收付款','否']],
[['证件正面','','file'],['证件背面','','file'],['人脸自拍','','file'],['居住地址证明','','file']]
]}
function verifyCapture(){document.querySelectorAll('#verify-form input').forEach(i=>{if(i.type==='checkbox')verifyDraft[i.name]=i.checked;else if(i.type==='file'){if(i.files.length)verifyDraft[i.name]=i.files[0].name}else verifyDraft[i.name]=i.value})}
function verifyRender(){const steps=person.type==='enterprise'?['企业信息','代表人与股东','证明文件']:['个人信息','地址与用途','证明文件'];const list=verifyFields()[verifyStep];modal((verifyService==='bank'?'银行':'卡片')+'认证',`<div class="progress">${steps.map((s,i)=>`<span class="${i===verifyStep?'active':''}">${i+1}. ${s}</span>`).join('')}</div><form id="verify-form"><div class="row">${list.map(([label,value,type],i)=>type==='file'?`<label class="field">${label}<input type="file" name="${label}" accept=".pdf,.jpg,.jpeg,.png"><span class="file-hint">${esc(verifyDraft[label]||'未选择文件')}</span></label>`:field('vf-'+i,label,verifyDraft[label]??(label==='企业名称'?db.name:''),type||'text').replace(`name="vf-${i}"`,`name="${label}"`)).join('')}</div>${verifyStep===2?'<label class="check"><input type="checkbox" name="agree" id="verify-agree">我确认演示资料并同意本次认证声明与授权。</label>':''}${note('使用虚构资料即可。这里只演示资料提交与审核，不执行接口级字段规则。')}${formError}<div class="dialog-foot">${btn('填入演示资料','verify-sample')}${verifyStep>0?btn('上一步','verify-back'):btn('取消','close')}<button class="button primary">${verifyStep===2?'提交认证':'下一步'}</button></div></form>`);bindForm('#verify-form',()=>{verifyCapture();if(verifyStep<2){verifyStep++;verifyRender();return}if(!verifyDraft.agree)return err('请先勾选声明与授权。');db.verification[verifyService]={status:'pending',data:verifyDraft};save();render();success('认证已提交','资料进入审核中，可从认证页模拟通过或补充资料。')})}
function review(service){if(db.verification[service].status!=='pending')return;modal('模拟审核结果',note('这是原型演示控制，不代表客户可自行审核。'),btn('需补充资料','review-reject',service)+btn('审核通过','review-approve',service,'primary'))}
function openbank(c='USD'){if(!gate('bank'))return;const choices=['USD','EUR','GBP'].filter(x=>!opened(x));if(!choices.length)return toast('所有演示币种均已开通。');if(!choices.includes(c))c=choices[0];modal('开通法币账户',`<div class="progress"><span class="active">1. 选择币种</span><span>2. 确认开通</span></div><form id="open-form">${select('currency','账户币种',choices,c)}${summary([['账户持有人',esc(db.name)]])}<label class="check"><input type="checkbox" id="terms">我同意所选服务的开户条款与授权。</label>${note('币种与通道用于流程演示：USD / Bridge，EUR、GBP / OpenPayd。地区可用性与渠道补充材料以实际系统为准。开户演示不扣费。')}${footerForm('继续')}</form>`);bindForm('#open-form',()=>{if(!$('#terms').checked)return err('请先同意开户条款与授权。');const cur=$('#currency').value;modal('确认开通',summary([['币种',cur],['通道',cur==='USD'?'Bridge':'OpenPayd'],['持有人',esc(db.name)]])+note('开通后生成演示账户信息。'),btn('返回','openbank',cur)+btn('确认开通','openbank-confirm',cur,'primary'))})}
function bankdetail(c){const a=db.accounts.find(a=>a.currency===c);if(!a)return;modal(c+' 收款账户',summary([['持有人',esc(db.name)],['币种',c],['银行名称','Demo Bank（演示）'],[c==='EUR'?'IBAN':'账户号码',`<span class="account-no">${esc(a.number)}</span>`],...(c==='GBP'?[['Sort Code','DEMO-GB']]:c==='USD'?[['ABA 路由号码','DEMO-US']]:[['SWIFT / BIC','DEMO-BIC']])])+note('以上均为无效演示银行信息，不能用于真实汇款。'),btn('复制收款信息','copy-bank',c)+btn('关闭','close','','primary'))}
function external(c='USD'){if(!gate('bank'))return;modal('添加外部同名账户',`<form id="external-form">${select('currency','币种',['USD','EUR','GBP'],c||'USD')}${field('holder','账户持有人',db.name,'text','readonly')}${field('label','账户名称','','text','placeholder="例如：我的收款账户"')}${field('bank-name','银行名称')}<div id="external-fields"></div>${field('country','开户国家 / 地区')}${note('持有人取自认证身份，不可修改。这里只演示本地银行收款路径，字段格式规则以接口为准。')}${footerForm('添加账户')}`);const draw=()=>{const cur=$('#currency').value;$('#external-fields').innerHTML=cur==='EUR'?field('account-number','IBAN')+field('routing','SWIFT / BIC'):field('account-number','账户号码')+field('routing',cur==='USD'?'ABA 路由号码':'Sort Code')+(cur==='USD'?select('account-type','账户类型',['Checking','Savings']):'');$('#country').value={USD:'美国',EUR:'德国',GBP:'英国'}[cur]};$('#currency').onchange=draw;draw();bindForm('#external-form',()=>{if(!$('#label').value.trim()||!$('#bank-name').value.trim()||!$('#account-number').value.trim())return err('请填写账户名称、银行名称与收款账号。');const currency=$('#currency').value,number=$('#account-number').value.trim();if(db.externals.some(a=>a.currency===currency&&a.number===number))return err('该账户已存在。');const a={id:uid(),label:$('#label').value,currency,number,bank:$('#bank-name').value,routing:$('#routing').value,country:$('#country').value,status:currency==='USD'?'approved':'pending'};db.externals.push(a);save();render();success('外部账户已添加',currency==='USD'?'美国账户无需姓名核验，已可用于演示出金。':'欧洲 / 英国账户需要姓名匹配，通过后才能出金。',btn('查看账户','external-detail',a.id,'primary'))})}
function externalDetail(id){const a=db.externals.find(a=>a.id===id);if(!a)return;modal('外部同名账户详情',summary([['账户名称',esc(a.label)],['持有人',esc(db.name)],['币种',a.currency],['银行',esc(a.bank)],['账户',esc(a.number)],['核验状态',badge(a.status)]])+note('欧洲 / 英国账户核验通过后可出金。'),(a.status==='pending'?btn('模拟核验通过','external-approve',a.id,'primary'):'')+btn('关闭','close'))}
function deposit(c=''){let choices=Object.keys(db.balances).filter(x=>!fiat(x)||opened(x));if(!choices.includes(c))c=choices[0];modal('入金',`<form id="deposit-form">${select('currency','到账资产',choices,c)}<div id="deposit-info"></div>${field('amount','演示入金金额','','text','inputmode="decimal" placeholder="0.00"')}${note('仅创建本地入金记录。到账前余额不增加，提交后可模拟到账。')}${footerForm('创建演示入金')}`);const draw=()=>{const cur=$('#currency').value;$('#deposit-info').innerHTML=fiat(cur)?summary([['收款持有人',esc(db.name)],['演示收款账户',esc(db.accounts.find(a=>a.currency===cur).number)]]):select('network','网络',['Ethereum','TRON'])+`<div class="copy-box">DEMO-ONLY-${cur}-NOT-A-REAL-ADDRESS</div>`};draw();$('#currency').onchange=draw;bindForm('#deposit-form',()=>{const n=amount();if(n===null)return;const currency=$('#currency').value;const t=addTx('入金',currency,n,'processing',{network:$('#network')?.value||'银行转账',before:db.balances[currency],after:null});save();render();success('入金记录已创建','等待到账。可进入详情模拟到账或失败。',btn('查看入金','tx',t.id,'primary'))})}
function totp(next=null){draft=next;modal('绑定身份验证器',`<form id="totp-form"><div class="progress"><span class="active">1. 添加身份验证器</span><span class="active">2. 输入验证码</span></div><p>打开身份验证器应用添加账户，再输入当前验证码。</p>${note('不显示真实密钥或二维码。演示验证码：246810。')}${field('otp','六位验证码','','text','inputmode="numeric" maxlength="6" autocomplete="off"')}${footerForm('完成绑定')}`);bindForm('#totp-form',()=>{if($('#otp').value!=='246810')return err('验证码不正确，请输入演示码 246810。');db.totp=true;save();render();const target=draft;draft=null;if(target?.action==='withdraw')withdraw(target.currency);else success('绑定完成','出金安全验证已启用。')})}
function withdraw(c='USD'){if(!c)c='USD';if(fiat(c)&&!gate('bank'))return;if(fiat(c)&&!opened(c))return openbank(c);if(!db.totp)return totp({action:'withdraw',currency:c});const accounts=db.externals.filter(a=>a.currency===c&&a.status==='approved');if(fiat(c)&&!accounts.length){modal('添加同名收款账户','<p>当前币种还没有可用的外部同名账户。先添加并完成核验，再进行出金。</p>',btn('取消','close')+btn('添加账户','external',c,'primary'));return}modal(fiat(c)?'出金':'加密资产提现',`<form id="withdraw-form">${summary([['支付资产',c],['可用余额',money(db.balances[c]/100)+' '+c]])}${fiat(c)?select('recipient','外部同名账户',accounts.map(a=>[a.id,a.label+' · '+a.number])):select('network','网络',['Ethereum','TRON'])+field('address','收款钱包地址','','text','placeholder="填写演示地址"')}${field('amount','出金金额','','text','inputmode="decimal" placeholder="0.00"')}${field('reference','备注（选填）')}${note('本次演示手续费为 0，不代表实际费率。确认提交后暂扣余额；处理失败将返还。')}${footerForm('核对并继续')}`);bindForm('#withdraw-form',()=>{const n=amount();if(n===null)return;if(n>db.balances[c])return err('可用余额不足。');if(!fiat(c)&&!$('#address').value.trim())return err('请填写收款地址。');const target=fiat(c)?accounts.find(a=>a.id===$('#recipient').value).number:$('#address').value;const req={currency:c,amount:n,target,reference:$('#reference').value,network:$('#network')?.value||'银行转账'};modal('核对出金并验证',`<form id="withdraw-confirm">${summary([['出金金额',money(n/100)+' '+c],['收款账户 / 地址',esc(target)],['手续费','0.00 '+c],['预计到账',money(n/100)+' '+c]])}${field('otp','身份验证器验证码','','text','inputmode="numeric" maxlength="6"')}${note('请输入 246810，确认后创建模拟出金。')}${footerForm('确认出金')}`);bindForm('#withdraw-confirm',()=>{if($('#otp').value!=='246810')return err('验证码不正确。');if(req.amount>db.balances[c])return err('可用余额已变动，请重新发起。');const before=db.balances[c];db.balances[c]-=req.amount;const tx=addTx('出金',c,-req.amount,'processing',{...req,amount:-req.amount,before,after:db.balances[c],fee:0});save();render();success('出金已提交','资金已暂扣，可在详情模拟完成或失败退款。',btn('查看出金','tx',tx.id,'primary'))})})}
const rates={USD:1,EUR:1.08,GBP:1.27,USDT:1,USDC:1};
function exchange(){const from=$('#from').value,to=$('#to').value,n=amount();if(n===null)return;if(from===to)return err('请选择不同的支付和到账资产。');if(n>db.balances[from])return err('支付资产余额不足。');if(fiat(to)&&!opened(to))return err('请先开通 '+to+' 法币账户。');const received=Math.round(n*rates[from]/rates[to]);if(received<=0)return err('到账金额小于演示精度，请提高金额。');const q={id:uid(),from,to,n,received,expires:Date.now()+60000};draft=q;modal('确认承兑报价',summary([['支付',money(n/100)+' '+from],['演示汇率','1 '+from+' = '+(rates[from]/rates[to]).toFixed(6)+' '+to],['手续费','0.00 '+from],['预计到账',money(received/100)+' '+to]])+note('演示报价有效期 60 秒，非真实市场报价。'),btn('取消','close')+btn('确认承兑','exchange-confirm',q.id,'primary'))}
function txDetail(id){const t=db.transactions.find(t=>t.id===id);if(!t)return;modal('交易详情',summary([['交易编号',esc(t.id)],['类型',t.type],['状态',badge(t.status)],['时间',t.date],['金额',money(t.amount/100)+' '+t.currency],...(t.target?[['收款账户 / 地址',esc(t.target)]]:[]),...(t.to?[['到账',money(t.received/100)+' '+t.to]]:[]),...(t.before!==undefined?[['变动前可用余额',money(t.before/100)+' '+t.currency]]:[]),...(t.after!==null&&t.after!==undefined?[['变动后可用余额',money(t.after/100)+' '+t.currency]]:[]),...(t.refundAfter!==undefined?[['已返还',money(-t.amount/100)+' '+t.currency],['返还后可用余额',money(t.refundAfter/100)+' '+t.currency]]:[]),...(t.reference?[['备注',esc(t.reference)]]:[])])+note('处理中记录可模拟处理结果；操作只生效一次。'),(t.status==='processing'?btn('模拟失败','tx-fail',t.id)+btn('模拟完成','tx-complete',t.id,'primary'):'')+btn('关闭','close'))}
function settle(id,ok){const t=db.transactions.find(t=>t.id===id);if(!t||t.status!=='processing')return toast('该交易已处理。');if(t.type==='入金'&&ok){t.before=db.balances[t.currency];db.balances[t.currency]+=t.amount;t.after=db.balances[t.currency]}if(t.type==='出金'&&!ok){t.refundBefore=db.balances[t.currency];db.balances[t.currency]-=t.amount;t.refundAfter=db.balances[t.currency]}t.status=ok?'completed':'failed';save();render();txDetail(id)}
function holder(){if(!gate('card'))return;modal('添加持卡人',`<form id="holder-form">${field('holder-name','持卡人姓名',person.type==='personal'?db.name:'')}${field('holder-email','邮箱',person.email,'email')}${field('holder-phone','手机号')}${note('持卡人信息参考实际卡流程；演示仅保存输入资料，不向上游提交。')}${footerForm('保存持卡人')}`);bindForm('#holder-form',()=>{if(!$('#holder-name').value.trim()||!$('#holder-email').value.trim())return err('请填写持卡人姓名与邮箱。');db.holders.push({id:uid(),name:$('#holder-name').value,email:$('#holder-email').value,phone:$('#holder-phone').value});save();render();success('持卡人已添加','现在可以选择持卡人并申请开卡。',btn('去开卡','applycard','','primary'))})}
function applycard(){if(!gate('card'))return;if(!db.holders.length)return holder();modal('申请开卡',`<form id="card-form">${select('product','卡片产品',[['virtual','Everyday 虚拟卡（演示）']])}${select('holder-id','持卡人',db.holders.map(h=>[h.id,h.name]))}${summary([['开卡费','10.00 USDT（演示）'],['可用余额',money(db.balances.USDT/100)+' USDT']])}<label class="check"><input type="checkbox" id="card-agree">已阅读卡片说明并确认开卡费。</label>${note('产品与费用为演示设定。开卡成功后扣除演示费用并写入交易记录。')}${footerForm('确认申请')}`);bindForm('#card-form',()=>{if(!$('#card-agree').checked)return err('请确认卡片说明与开卡费。');if(db.balances.USDT<1000)return err('USDT 余额不足，请先入金。');const h=db.holders.find(h=>h.id===$('#holder-id').value);const before=db.balances.USDT;db.balances.USDT-=1000;const card={id:uid(),product:'Everyday 虚拟卡',holder:h.name,email:h.email,last4:String(1000+db.cards.length),date:now()};db.cards.push(card);addTx('开卡','USDT',-1000,'completed',{before,after:db.balances.USDT,reference:card.product});save();render();success('开卡成功','已扣除 10.00 USDT 演示开卡费。',btn('查看卡片','carddetail',card.id,'primary'))})}
function product(id){const p=products.find(p=>p.id===id);if(!p)return;modal(p.name,`<div class="product-art">${p.art}</div><p>${p.desc}</p>${summary([['商品类型',p.kind],['兑换积分',p.cost],['可用积分',db.points],['库存','有货（演示）']])}${note('商品仅用于展示兑换流程，不实际发货或兑现。')}`,btn('取消','close')+btn('立即兑换','redeem',id,'primary'))}
function redeem(id){const p=products.find(p=>p.id===id);if(!p)return;if(db.points<p.cost){modal('积分不足',`<p>兑换需要 ${p.cost} 积分，当前有 ${db.points} 积分。</p>`,btn('关闭','close')+btn('去邀请好友','goto','referral','primary'));return}modal('确认兑换',`<form id="redeem-form">${summary([['商品',p.name],['所需积分',p.cost],['兑换后剩余',db.points-p.cost]])}${p.kind==='实体商品'?field('receiver','收件人')+field('phone','联系电话')+field('shipping','收货地址'):field('delivery-email','领取邮箱',person.email,'email')}${note('只填写演示信息；不会寄送或发送邮件。')}${footerForm('确认兑换')}`);bindForm('#redeem-form',()=>{let address=p.kind==='实体商品'?$('#shipping').value:$('#delivery-email').value;if(!address.trim()||(p.kind==='实体商品'&&(!$('#receiver').value.trim()||!$('#phone').value.trim())))return err('请填写完整的收货或领取信息。');if(db.points<p.cost)return err('当前积分不足。');const o={id:uid(),name:p.name,cost:p.cost,kind:p.kind,date:now(),address,receiver:$('#receiver')?.value||'',phone:$('#phone')?.value||'',status:p.kind==='实体商品'?'待收货':'待领取'};db.points-=p.cost;db.pointLog.unshift({id:uid(),date:now(),amount:-p.cost,title:'兑换 '+p.name});db.orders.unshift(o);save();render();success('兑换成功','积分已扣除，可在订单详情查看领取或收货信息。',btn('查看订单','order',o.id,'primary'))})}
function order(id){const o=db.orders.find(o=>o.id===id);if(!o)return;modal('兑换订单',summary([['订单号',esc(o.id)],['商品',esc(o.name)],['兑换积分',o.cost],['状态',badge(o.status)],['收货 / 领取信息',esc(o.address)],...(o.receiver?[['收件人',esc(o.receiver)],['联系电话',esc(o.phone)]]:[])])+note('履约操作为演示，不会实际发货。'),(o.status==='待收货'?btn('模拟确认收货','order-complete',o.id,'primary'):o.status==='待领取'?btn('领取权益','order-complete',o.id,'primary'):'')+btn('关闭','close'))}
async function copyText(text){try{await navigator.clipboard.writeText(text);toast('已复制。')}catch{modal('复制内容',`<textarea id="copy-text" rows="5" readonly>${esc(text)}</textarea><p class="muted">当前浏览器限制自动复制，请选中内容手动复制。</p>`,btn('关闭','close'));$('#copy-text').select()}}
const actions={close,goto:v=>{close();location.hash=v},verify,review,'verify-sample':()=>{verifyFields()[verifyStep].forEach(([k,v,t])=>{if(t==='file')verifyDraft[k]='演示-'+k+'.pdf';else verifyDraft[k]=v});verifyRender();if($('#verify-agree'))$('#verify-agree').checked=true},'verify-back':()=>{verifyCapture();verifyStep--;verifyRender()},'review-approve':v=>{if(db.verification[v].status!=='pending')return;db.verification[v].status='approved';save();close();render();toast('已模拟审核通过。')},'review-reject':v=>{if(db.verification[v].status!=='pending')return;db.verification[v].status='rejected';save();close();render()},openbank,'openbank-confirm':c=>{if(opened(c)||db.verification.bank.status!=='approved')return;db.accounts.push({currency:c,number:'DEMO-'+c+'-000001',date:now()});save();render();bankdetail(c)},bankdetail,'copy-bank':c=>{const a=db.accounts.find(a=>a.currency===c);if(a)copyText('演示信息，不可汇款\n'+db.name+'\n'+c+'\n'+a.number)},external,'external-detail':externalDetail,'external-approve':id=>{const a=db.externals.find(a=>a.id===id);if(a?.status==='pending'){a.status='approved';save();render();externalDetail(id)}},deposit,withdraw,totp:()=>totp(),tx:txDetail,'tx-complete':id=>settle(id,true),'tx-fail':id=>settle(id,false),'exchange-confirm':id=>{const q=draft;if(!q||q.id!==id)return;if(Date.now()>q.expires){draft=null;return modal('报价已过期','<p>请重新获取报价后确认。</p>',btn('重新报价','close','','primary'))}if(db.balances[q.from]<q.n)return toast('余额不足，请重新获取报价。');const before=db.balances[q.from];db.balances[q.from]-=q.n;db.balances[q.to]+=q.received;addTx('承兑',q.from,-q.n,'completed',{to:q.to,received:q.received,before,after:db.balances[q.from]});draft=null;save();render();success('承兑完成',`已到账 ${money(q.received/100)} ${q.to}。余额和交易记录已更新。`)},holder,applycard,carddetail:id=>{const c=db.cards.find(c=>c.id===id);if(c)modal('卡片详情',summary([['卡产品',esc(c.product)],['持卡人',esc(c.holder)],['邮箱',esc(c.email)],['卡号后四位',esc(c.last4)],['开卡时间',c.date],['状态','已开卡（演示）']])+note('不生成真实卡号、有效期或安全码。'),btn('关闭','close'))},'copy-referral':()=>copyText(referralURL()),invite:()=>{modal('模拟好友注册',`<form id="invite-form">${field('friend','好友名称','','text','placeholder="填写演示名称"')}${note('每次有效模拟注册奖励 100 积分；同名演示好友不会重复奖励。')}${footerForm('模拟注册完成')}`);bindForm('#invite-form',()=>{const name=$('#friend').value.trim();if(!name)return err('请填写演示好友名称。');if(db.invites.some(i=>i.name===name))return err('该演示好友已存在。');db.invites.push({id:uid(),name,date:now(),verified:false});db.points+=100;db.pointLog.unshift({id:uid(),date:now(),amount:100,title:'邀请好友 '+name});save();render();success('邀请成果已更新','已新增一位好友并获得 100 演示积分。现金返佣余额不变。')})},product,redeem,order,'order-complete':id=>{const o=db.orders.find(o=>o.id===id);if(!o||!['待收货','待领取'].includes(o.status))return;o.status=o.kind==='实体商品'?'已收货':'已领取';save();render();order(id)},page:v=>{filter.page+=Number(v);render()},'reset-filter':()=>{filter={type:'all',status:'all',q:'',page:1};render()},'reset-empty':()=>resetConfirm(false),'reset-seed':()=>resetConfirm(true),'reset-confirm':v=>{db=initial(v==='seed');save();close();filter={type:'all',status:'all',q:'',page:1};render();toast('当前账户演示数据已重置。')}};
function resetConfirm(seed){modal('重置当前账户',`<p>将清除当前账户的认证、账户、交易、卡片、邀请与订单记录。</p><p>${seed?'重新载入 2,500 USDT 与 1,200 积分。':'资金与积分归零。'}</p>`,btn('取消','close')+btn('确认重置','reset-confirm',seed?'seed':'empty','primary'))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){e.preventDefault();const action=actions[b.dataset.action];if(action)action(b.dataset.value)}});
document.addEventListener('submit',e=>{if(e.target.id==='exchange-form'){e.preventDefault();exchange()}if(e.target.id==='filter-form'){e.preventDefault();const f=new FormData(e.target);filter={q:f.get('q'),type:f.get('type'),status:f.get('status'),page:1};render()}});
document.addEventListener('change',e=>{if(e.target.id==='from')$('#from-balance').textContent='可用 '+money(db.balances[e.target.value]/100)+' '+e.target.value});
$('#menu').onclick=()=>{const expanded=$('.side').classList.toggle('expanded');$('#menu').setAttribute('aria-expanded',expanded)};
$('#logout').onclick=()=>{try{localStorage.removeItem('client-demo-session')}catch{}location.href=AUTH};
window.addEventListener('hashchange',()=>{close();$('.side').classList.remove('expanded');$('#menu').setAttribute('aria-expanded','false');render();window.scrollTo(0,0)});
window.addEventListener('storage',e=>{if(e.key===key){db=read(key,db);close();render();toast('另一窗口已更新当前账户数据。')}});
render();
